"""Tiny wc. Usage: python wc.py [--lines] [--words] [--chars] FILE [--top N]"""
import argparse
import sys


def count(text):
    return {"lines": len(text.splitlines()), "words": len(text.split())}


def main(argv=None):
    ap = argparse.ArgumentParser()
    ap.add_argument("file")
    ap.add_argument("--lines", action="store_true")
    ap.add_argument("--words", action="store_true")
    ap.add_argument("--chars", action="store_true")
    ap.add_argument("--top", type=int, default=0)
    a = ap.parse_args(argv)
    with open(a.file) as f:
        text = f.read()
    c = count(text)
    selected = []
    if getattr(a, "lines", False):
        selected.append("lines")
    if getattr(a, "words", False):
        selected.append("words")
    if getattr(a, "chars", False):
        selected.append("chars")
    if a.top > 0:
        selected.append("top")
    for k in selected:
        if k == "top":
            # Get top N words by frequency
            words = c["words"]
            if words == 0:
                words = []
            freq_dict = {}
            for word in text.split():
                freq_dict[word] = freq_dict.get(word, 0) + 1
            sorted_items = sorted(freq_dict.items(), key=lambda x: x[1], reverse=True)
            top_words = sorted_items[:a.top] if a.top > 0 else []
            for word, freq in top_words:
                print(f"{word} {freq}")
            return
    for k in selected:
        print(f"{k} {c[k]}")


if __name__ == "__main__":
    sys.exit(main())

"""Tiny wc. Usage: python wc.py [--lines] [--words] [--chars] [--top N] FILE"""
import argparse
import sys
from collections import Counter


def count(text):
    return {"lines": len(text.splitlines()), "words": len(text.split())}


def top_words(text, n):
    return Counter(text.split()).most_common(n)


def main(argv=None):
    ap = argparse.ArgumentParser()
    ap.add_argument("file")
    ap.add_argument("--lines", action="store_true")
    ap.add_argument("--words", action="store_true")
    ap.add_argument("--chars", action="store_true")
    ap.add_argument("--top", type=int)
    a = ap.parse_args(argv)
    with open(a.file) as f:
        text = f.read()
    selected = [k for k in ("lines", "words", "chars") if getattr(a, k)] or ["lines", "words"]
    for k in selected:
        print(f"{k} {count(text)[k]}")
    if a.top:
        for word, c in top_words(text, a.top):
            print(f"{word} {c}")
    return 0


if __name__ == "__main__":
    sys.exit(main())

