import argparse
import re
import sys


def count(text):
    return {"lines": len(text.splitlines()), "words": len(text.split())}


def main(argv=None):
    ap = argparse.ArgumentParser()
    ap.add_argument("file")
    ap.add_argument("--lines", action="store_true")
    ap.add_argument("--words", action="store_true")
    ap.add_argument("--chars", action="store_true")
    ap.add_argument("--top", type=int)
    a = ap.parse_args(argv)
    with open(a.file) as f:
        text = f.read()
    c = count(text)
    selected = []
    if a.chars:
        selected.append("chars")
    if a.top:
        selected.append("top")
    if a.top:
        counts = re.findall(r"[^\W\d_]+", text.lower())
        counts = [c for c in counts if c]
        common = sorted(counts, key=counts.count, reverse=True)[:a.top]
        for word in common:
            print(f"{word} {counts.count(word)}")
    if a.chars:
        print(f"chars {c.chars}")
    if a.top:
        for word in selected:
            print(f"{word} {c[word]}")
    return 0


if __name__ == "__main__":
    sys.exit(main())

